style.object:
: full animation + script.
         - : static only — browsers do
           not run scripts in image-loaded SVGs. Rings will be invisible because
           the activation script never runs to add .rt-anim. If you need a static
           rendering use the no-script fallback class (see below). */

    .rt-ring{transform-box:fill-box;transform-origin:center;opacity:0;}

    /* When .rt-anim is present on the root svg, run entrance + perpetual motion */
    .rt-anim .rt-r4{
      animation:rt-mark-in 1.0s cubic-bezier(0.22,1,0.36,1) 0.0s both,
                rt-scale-4 5.7s ease-in-out 1.4s infinite;
    }
    .rt-anim .rt-r3{
      animation:rt-mark-in 1.0s cubic-bezier(0.22,1,0.36,1) 0.18s both,
                rt-stretch-3 6.1s ease-in-out 1.4s infinite,
                rt-pulse-3 3.8s ease-in-out 1.4s infinite;
    }
    .rt-anim .rt-r2{
      animation:rt-mark-in 1.0s cubic-bezier(0.22,1,0.36,1) 0.36s both,
                rt-rotate-2 5.3s ease-in-out 1.4s infinite,
                rt-pulse-2 3.1s ease-in-out 1.4s infinite;
    }
    .rt-anim .rt-r1{
      animation:rt-mark-in 1.0s cubic-bezier(0.22,1,0.36,1) 0.54s both,
                rt-scale-1 4.7s ease-in-out 1.4s infinite,
                rt-pulse-1 5.9s ease-in-out 1.4s infinite;
    }
    .rt-anim .rt-word{
      animation:rt-word-in 0.9s cubic-bezier(0.22,1,0.36,1) 0.7s both;
    }
    .rt-word{opacity:0;transform:translateX(-8px);transform-box:fill-box;transform-origin:left center;}

    /* Pause perpetual motion when the parent document hides */
    .paused .rt-ring{animation-play-state:paused!important;}

    /* Static fallback class: use this instead of .rt-anim when scripts can't run
       (e.g. SVG loaded via ). Skips entrance, shows rings at rest. */
    .rt-static .rt-ring,.rt-static .rt-word{opacity:1;transform:none;}

    @keyframes rt-mark-in{
      0%   { opacity:0; transform:scale(0.15); }
      30%  { opacity:1; }
      100% { opacity:1; transform:scale(1); }
    }
    @keyframes rt-word-in{
      from { opacity:0; transform:translateX(-8px); }
      to   { opacity:1; transform:translateX(0); }
    }

    @keyframes rt-scale-1   { 0%,100%{transform:scale(1);}      50%{transform:scale(1.10);} }
    @keyframes rt-pulse-1   { 0%,100%{filter:brightness(1);}    50%{filter:brightness(1.30);} }
    @keyframes rt-rotate-2  { 0%,100%{transform:rotate(0);}     50%{transform:rotate(-8deg);} }
    @keyframes rt-pulse-2   { 0%,100%{filter:brightness(1);}    50%{filter:brightness(0.70);} }
    @keyframes rt-stretch-3 { 0%,100%{transform:scale(1,1);}    50%{transform:scale(1.20,0.80);} }
    @keyframes rt-pulse-3   { 0%,100%{filter:brightness(1);}    50%{filter:brightness(1.42);} }
    @keyframes rt-scale-4   { 0%,100%{transform:scale(1);}      50%{transform:scale(0.86);} }

    @media (prefers-reduced-motion: reduce){
      .rt-anim .rt-ring,.rt-anim .rt-word{
        animation:none!important;opacity:1!important;transform:none!important;filter:none!important;
      }
    }

svg.script:

// Activation: add .rt-anim to play entrance + perpetual motion.
// Pause on parent-document visibility change (works when this SVG is loaded
// as <object> or inlined; <img>-loaded SVGs do not run this script).
(function(){
  var svg = document.documentElement;
  if (!svg) return;
  svg.classList.add('rt-anim');
  try {
    var doc = (document.defaultView && document.defaultView.parent && document.defaultView.parent.document) || document;
    doc.addEventListener('visibilitychange', function(){
      if (doc.hidden) svg.classList.add('paused');
      else svg.classList.remove('paused');
    });
  } catch(e){ /* cross-origin or unsupported — animation just keeps running */ }
})();
